PREFIX BO: <http://example.org/BO/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?range 
WHERE {
    BO:hasThingProperty rdfs:range ?range .
}

PREFIX BO: <http://example.com/BO/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?dataPoint
WHERE {
    ?service rdf:type BO:Service .
    {
        ?service BO:hasInputDataPoint ?dataPoint .
    } UNION {
        ?service BO:hasOutputDataPoint ?dataPoint .
    }
}

PREFIX BO: <http://example.com/BO/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?objectProperty
WHERE {
    ?objectProperty rdf:type owl:ObjectProperty .
    VALUES ?objectProperty { BO:hasOperation BO:hasInput BO:hasOutputDataPoint BO:hasSubService BO:describes BO:hasMetaData BO:hasThingRelation BO:hasSubStructure BO:hasInputDataPoint }
}

PREFIX BO: <http://example.com/BO/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?variable ?operation ?conversion
WHERE {
    ?variable rdf:type BO:Variable .
    ?variable BO:hasConversion ?conversion .
    ?conversion BO:convertsTo ?targetVariable .
    ?operation rdf:type BO:Operation .
    { 
        ?operation BO:OperationInput ?variable .
    } UNION {
        ?operation BO:OperationOutput ?variable .
    }
    FILTER NOT EXISTS { ?conversion a owl:Nothing }
}

PREFIX BO: <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?device ?variable ?value
WHERE {
    ?device rdf:type BO:Device .
    ?variable rdf:type BO:SimpleTypeVariable .
    ?variable BO:hasValue ?value .
    OPTIONAL { 
        ?device BO:exposesCommand ?command .
    }
    OPTIONAL { 
        ?variable BO:isDataList ?isDataList .
    }
    ?variable BO:hasThingAnnotation ?annotation .
}

PREFIX BO: <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?thing ?annotation ?command
WHERE {
    ?thing rdf:type BO:Thing .
    ?thing BO:hasThingAnnotation ?annotation .
    OPTIONAL { 
        ?thing BO:exposesCommand ?command .
    }
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?minInclusive ?maxInclusive
WHERE {
    ?variable a BO:SimpleTypeVariable .
    OPTIONAL { ?variable BO:hasDataRestriction_minInclusive ?minInclusive . }
    OPTIONAL { ?variable BO:hasDataRestriction_maxInclusive ?maxInclusive . }
    FILTER((BOUND(?minInclusive) && BOUND(?maxInclusive)) || (!BOUND(?minInclusive) && !BOUND(?maxInclusive)))
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?x
WHERE {
    ?x rdf:type BO:SimpleTypeVariable .
    FILTER NOT EXISTS { 
        ?x BO:hasDataRestriction_minInclusive ?y . 
        ?y rdf:type xsd:integer 
    }
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
