    ?variable rdf:type BO:SimpleTypeVariable .
    OPTIONAL { ?variable BO:hasDataRestriction_minExclusive ?minExclusive . }
    OPTIONAL { ?variable BO:hasDataRestriction_maxExclusive ?maxExclusive . }
    FILTER((BOUND(?minExclusive) && BOUND(?maxExclusive)) || (BOUND(?minExclusive) && !BOUND(?maxExclusive)) || (!BOUND(?minExclusive) && BOUND(?maxExclusive)))
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
