    ?variable BO:hasDataRestriction_minInclusive ?minInclusive .
    FILTER NOT EXISTS { 
        ?variable BO:hasDataRestriction_maxInclusive ?maxInclusive .
    }
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?simpleTypeVariable ?minLength ?maxLength
WHERE {
    ?simpleTypeVariable rdf:type BO:SimpleTypeVariable .
    OPTIONAL { 
        ?simpleTypeVariable BO:hasDataRestriction_minLength ?minLength . 
        FILTER (datatype(?minLength) = xsd:nonNegativeInteger)
    }
    OPTIONAL { 
        ?simpleTypeVariable BO:hasDataRestriction_maxLength ?maxLength . 
        FILTER (datatype(?maxLength) = xsd:nonNegativeInteger)
    }
    FILTER (?minLength != "" || ?maxLength != "")
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
