SELECT ?x
WHERE {
    ?x rdf:type BO:SimpleTypeVariable .
    OPTIONAL { ?x BO:hasDataRestriction_pattern ?y . }
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?x
WHERE {
    ?x rdf:type BO:SimpleTypeVariable .
    OPTIONAL { ?x BO:hasDataRestriction_minInclusive ?minInclusive . }
    OPTIONAL { ?x BO:hasDataRestriction_maxInclusive ?maxInclusive . }
    OPTIONAL { ?x BO:hasDataRestriction_length ?length . }
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?simpleTypeVariable ?dataRestriction
WHERE {
    ?simpleTypeVariable rdf:type BO:SimpleTypeVariable .
    ?simpleTypeVariable BO:hasDataRestriction ?dataRestriction .
    OPTIONAL { 
        ?simpleTypeVariable BO:hasDataRestriction_minInclusive ?minInclusive .
        ?simpleTypeVariable BO:hasDataRestriction_maxInclusive ?maxInclusive .
        FILTER (!(xsd:integer(?dataRestriction) >= xsd:integer(?minInclusive) && xsd:integer(?dataRestriction) <= xsd:integer(?maxInclusive))) .
    }
    FILTER(EXISTS {
        ?simpleTypeVariable BO:hasDataRestriction_minInclusive ?minInclusive .
        ?simpleTypeVariable BO:hasDataRestriction_maxInclusive ?maxInclusive .
    } && BOUND(?dataRestriction))
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?variable ?minInclusive ?maxInclusive ?minExclusive ?maxExclusive ?pattern ?length ?maxLength ?minLength
WHERE {
    ?variable rdf:type BO:SimpleTypeVariable.
    OPTIONAL { ?variable BO:hasDataRestriction_minInclusive ?minInclusive. }
    OPTIONAL { ?variable BO:hasDataRestriction_maxInclusive ?maxInclusive. }
    OPTIONAL { ?variable BO:hasDataRestriction_minExclusive ?minExclusive. }
    OPTIONAL { ?variable BO:hasDataRestriction_maxExclusive ?maxExclusive. }
    OPTIONAL { ?variable BO:hasDataRestriction_pattern ?pattern. }
    OPTIONAL { ?variable BO:hasDataRestriction_length ?length. }
    OPTIONAL { ?variable BO:hasDataRestriction_maxLength ?maxLength. }
    OPTIONAL { ?variable BO:hasDataRestriction_minLength ?minLength. }
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?areaNetwork
WHERE {
    ?areaNetwork rdf:type BO:AreaNetwork .
    OPTIONAL { ?areaNetwork BO:netTechnologyPhysicalStandard ?physicalStandard . }
    OPTIONAL { ?areaNetwork BO:netTechnologyCommunicationProtocol ?communicationProtocol . }
}

PREFIX BO: <http://example.org/BO/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?interworkedDevice ?areaNetwork ?netTechnologyPhysicalStandard ?netTechnologyCommunicationProtocol
WHERE {
    ?interworkedDevice rdf:type BO:InterworkedDevice .
    ?interworkedDevice BO:isPartOf ?areaNetwork .
    ?areaNetwork rdf:type BO:AreaNetwork .
    OPTIONAL { 
        ?areaNetwork BO:netTechnologyPhysicalStandard ?netTechnologyPhysicalStandard . 
        FILTER (datatype(?netTechnologyPhysicalStandard) = xsd:string)
    }
    OPTIONAL { 
        ?areaNetwork BO:netTechnologyCommunicationProtocol ?netTechnologyCommunicationProtocol . 
        FILTER (datatype(?netTechnologyCommunicationProtocol) = xsd:string)
    }
}
